#include <stdio.h>

int main(void)
{
    int values[3];
    int count = 0;
    values[count++] = 4;
    values[count++] = 9;
    int popped = values[--count];
    printf("%d %d\n", popped, count);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int values[] = {4, 9};
    int count = 2;
    int top = values[count - 1];
    printf("%d %d\n", top, count);
    return 0;
}

#include <stdio.h>

int main(void)
{
    char text[] = "(()";
    int count = 0;
    for (int i = 0; text[i] != '\0'; ++i) {
        if (text[i] == '(') {
            ++count;
        } else {
            --count;
        }
    }
    printf("%d\n", count);
    return 0;
}
